const lockNotificationHour = `-- name: LockNotificationHour :one
INSERT INTO notification_hours (organization_id, hour) VALUES ($1, $2)
ON CONFLICT (organization_id, hour) DO UPDATE SET n = notification_hours.n
RETURNING n, dropped
`

type LockNotificationHourParams struct {
	OrganizationID pgtype.UUID
	Hour           pgtype.Timestamptz
}

type LockNotificationHourRow struct {
	N       int32
	Dropped int32
}

// Locks the hour's row so concurrent publishers count correctly.
func (q *Queries) LockNotificationHour(ctx context.Context, arg LockNotificationHourParams) (LockNotificationHourRow, error) {
	row := q.db.QueryRow(ctx, lockNotificationHour, arg.OrganizationID, arg.Hour)
	var i LockNotificationHourRow
	err := row.Scan(&i.N, &i.Dropped)
	return i, err
}

